use std::io::{self, Write};

fn main() {
    println!("¡Hola desde Raxorin Studio!");

    print!("¿Cómo te llamas? ");
    io::stdout().flush().unwrap();

    let mut nombre = String::new();
    io::stdin().read_line(&mut nombre).unwrap();

    println!("¡Mucho gusto, {}!", nombre.trim());
}

